(() => {
  const refresh = async (el) => {
    const url = el.getAttribute("hx-get");
    if (!url) return;
    const response = await fetch(url, {headers: {"HX-Request": "true"}});
    if (response.ok) el.innerHTML = await response.text();
  };
  const boot = () => {
    document.querySelectorAll("[hx-get][hx-trigger^='every ']").forEach((el) => {
      const match = el.getAttribute("hx-trigger").match(/every\s+(\d+)s/);
      const seconds = match ? Number(match[1]) : 5;
      if (el.dataset.htmxLiteStarted) return;
      el.dataset.htmxLiteStarted = "1";
      setInterval(() => refresh(el), seconds * 1000);
    });
  };
  document.addEventListener("DOMContentLoaded", boot);
})();

